def find_Rotations(s):
    n = len(s)
    dp = [[0] * n for _ in range(n + 1)]

    # Initialize the dp array
    for i in range(n + 1):
        dp[i][0] = 0

    # Fill the dp array
    for i in range(n + 1):
        for j in range(n + 1):
            if s[i - 1] == s[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # The answer is the minimum number of rotations
    return dp[n][n]

